<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('sales');$pageTitle='Sales Entry';$activeMenu='sales-entry';$errors=[];
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$token=$_GET['token']??'';if(!hash_equals(csrf_token(),$token)){http_response_code(419);exit('Invalid token');}db()->prepare('DELETE FROM sales_records WHERE id=?')->execute([$id]);log_activity('DELETE','Sales','Deleted sales record #'.$id);flash('success','Sales record deleted.');redirect('sales/entry.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$person=(int)$_POST['salesperson_id'];$dept=(int)$_POST['department_id'];$month=$_POST['sales_month'].'-01';$actual=(float)$_POST['actual_sales'];$target=(float)($_POST['sales_target']??0);if(!$person||!$dept||!valid_date($month)||$actual<0)$errors[]='Please enter valid sales information.';if($target<=0){$q=db()->prepare('SELECT target_amount FROM sales_targets WHERE salesperson_id=? AND target_month=? LIMIT 1');$q->execute([$person,$month]);$target=(float)($q->fetchColumn()?:0);}if($target<=0)$errors[]='Set a positive sales target or enter a target amount.';if(!$errors){$s=db()->prepare('INSERT INTO sales_records(salesperson_id,department_id,sales_month,sales_target,actual_sales,created_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE department_id=VALUES(department_id),sales_target=VALUES(sales_target),actual_sales=VALUES(actual_sales),updated_at=NOW()');$s->execute([$person,$dept,$month,$target,$actual,current_user()['id']]);log_activity('UPSERT','Sales','Saved sales record for user #'.$person.' '.$month);flash('success','Sales performance saved.');redirect('sales/entry.php');}}
$users=users_for_select();$departments=departments();$rows=db()->query("SELECT sr.*,CONCAT(u.first_name,' ',u.last_name) person,d.name department,ROUND((sr.actual_sales/NULLIF(sr.sales_target,0))*100,2) achievement FROM sales_records sr JOIN users u ON u.id=sr.salesperson_id JOIN departments d ON d.id=sr.department_id ORDER BY sr.sales_month DESC,sr.actual_sales DESC")->fetchAll();require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Sales Entry</h1><p>Record monthly target and actual sales performance.</p></div></div><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="row g-3"><div class="col-xl-4"><div class="card-panel"><div class="card-head"><h2 class="section-title">Add / Update Record</h2></div><div class="card-body"><form method="post"><?=csrf_field()?><div class="mb-3"><label class="form-label">Sales Person</label><select class="form-select" name="salesperson_id" required><option value="">Select user</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['full_name'].' — '.$u['role_name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Department</label><select class="form-select" name="department_id" required><?php foreach($departments as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Month</label><input class="form-control" type="month" name="sales_month" value="<?=e(date('Y-m'))?>" required></div><div class="mb-3"><label class="form-label">Sales Target</label><input class="form-control" type="number" step=".01" min="0" name="sales_target" placeholder="Auto-uses saved target if blank"></div><div class="mb-3"><label class="form-label">Actual Sales</label><input class="form-control" type="number" step=".01" min="0" name="actual_sales" required></div><button class="btn btn-primary w-100">Save Sales Record</button></form></div></div></div><div class="col-xl-8"><div class="card-panel"><div class="card-body"><div class="table-responsive"><table class="table data-table"><thead><tr><th>Month</th><th>Sales Person</th><th>Department</th><th class="text-end">Target</th><th class="text-end">Actual</th><th>Achievement</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('M Y',strtotime($r['sales_month'])))?></td><td><?=e($r['person'])?></td><td><?=e($r['department'])?></td><td class="text-end"><?=money($r['sales_target'])?></td><td class="text-end"><?=money($r['actual_sales'])?></td><td><strong><?=number_format((float)$r['achievement'],1)?>%</strong></td><td><a data-confirm="Delete this sales record?" class="btn btn-sm btn-light border text-danger" href="<?=e(url('sales/entry.php?delete='.$r['id'].'&token='.csrf_token()))?>"><i class="fa-solid fa-trash"></i></a></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
